const runSetQueuedReason = `-- name: RunSetQueuedReason :execrows
UPDATE runs
SET queued_reason = $1,
	worker_wait_since = CASE
		WHEN $1::text = 'waiting_for_worker' AND queued_reason <> 'waiting_for_worker' THEN $2::timestamptz
		ELSE worker_wait_since
	END
WHERE status = 'queued'
	AND worker_id = $3
	AND task_id = $4
	AND COALESCE(next_attempt_at, due_at) <= $2
	AND queued_reason <> $1
`

